// ============================================================
// CONFIG: Bid4Assets County Storefronts
// ============================================================
// Update monthly from https://www.bid4assets.com/county-tax-sales
// ============================================================

const counties = [
  { slug: 'ClarkWAFeb26', county: 'Clark County', state: 'WA' },
  { slug: 'ImperialFeb26', county: 'Imperial County', state: 'CA' },
  { slug: 'ShastaFeb26', county: 'Shasta County', state: 'CA' },
  { slug: 'AlamedaMar26', county: 'Alameda County', state: 'CA' },
  { slug: 'SanJoaquinMar26', county: 'San Joaquin County', state: 'CA' },
  { slug: 'MontereyMar26', county: 'Monterey County', state: 'CA' },
  { slug: 'AmadorMar26', county: 'Amador County', state: 'CA' },
  { slug: 'LanderNVMar26', county: 'Lander County', state: 'NV' },
  { slug: 'MasonWAMar26', county: 'Mason County', state: 'WA' },
  { slug: 'ElkoNVApr26', county: 'Elko County', state: 'NV' },
  { slug: 'RiversideApr26', county: 'Riverside County', state: 'CA' },
];

return counties.map(c => ({
  json: {
    slug: c.slug,
    county: c.county,
    state: c.state,
    storefrontUrl: `https://www.bid4assets.com/storefront/${c.slug}`,
  }
}));

// ============================================================
// PARSE JSON API RESPONSE - PRODUCTION v5
// ============================================================
// Only passes Active + Upcoming auctions to the Hub.
// Skips Withdrawn, Sold, and Closed entries.
// ============================================================

const items = $input.all();
const results = [];
let skipped = 0;

for (const item of items) {
  let auctions = [];

  if (Array.isArray(item.json.data)) {
    auctions = item.json.data;
  } else if (item.json.Data && Array.isArray(item.json.Data)) {
    auctions = item.json.Data;
  } else if (item.json.auctionID || item.json.AuctionID) {
    auctions = [item.json];
  }

  if (auctions.length === 0) continue;

  for (const a of auctions) {
    const title = a.asset_title || a.Asset_title || '';
    const auctionId = a.auctionID || a.AuctionID || '';
    const bidAmount = a.currentBidAmount || a.CurrentBidAmount || a.minimumBid || a.MinimumBid || 0;
    const openTime = a.bidOpenTime || a.BidOpenTime || '';
    const closeTime = a.actualCloseTime || a.ActualCloseTime || a.bidCloseTime || a.BidCloseTime || '';
    const liveDate = a.liveDate || a.LiveDate || '';
    const timeRemaining = a.timeRemaining || a.TimeRemaining || '';
    const locState = a.locatedState || a.LocatedState || '';

    // --- Determine status first (to filter early) ---
    const tr = timeRemaining.toLowerCase();
    const isWithdrawn = title.includes('***Withdrawn***');

    if (isWithdrawn) { skipped++; continue; }
    if (tr === 'sold' || tr === 'closed') { skipped++; continue; }

    // --- Status ---
    let status = 'Active';
    if (tr.includes('preview')) {
      status = 'Upcoming';
    }

    // --- Property Address ---
    let address = title || `Auction ${auctionId}`;

    // --- County ---
    let county = 'N/A';
    const cleanTitle = title.trim();
    const countyMatch = cleanTitle.match(/^(.+?County)/i);
    if (countyMatch) county = countyMatch[1].trim();

    // --- State ---
    let state = locState || '';
    if (!state) {
      const stateMatch = cleanTitle.match(/County,?\s*([A-Z]{2})/i);
      if (stateMatch) state = stateMatch[1].toUpperCase();
    }

    // --- Current Bid ---
    let bid = typeof bidAmount === 'number' ? bidAmount : 0;

    // --- Bidding Date ---
    let biddingDate = 'N/A';
    const dateSource = openTime || liveDate || '';
    if (dateSource) {
      try {
        const dt = new Date(dateSource);
        if (!isNaN(dt.getTime())) {
          biddingDate = dt.toLocaleDateString('en-US', {
            month: 'long', day: 'numeric', year: 'numeric',
            timeZone: 'America/New_York'
          });
        }
      } catch (e) {}
    }

    // --- Sale Date ---
    let saleDate = 'N/A';
    if (closeTime) {
      try {
        const dt = new Date(closeTime);
        if (!isNaN(dt.getTime())) {
          saleDate = dt.toLocaleDateString('en-US', {
            month: 'long', day: 'numeric', year: 'numeric',
            timeZone: 'America/New_York'
          });
        }
      } catch (e) {}
    }

    // --- Bidding Time ---
    let biddingTime = 'Check Listing';
    if (closeTime) {
      try {
        const dt = new Date(closeTime);
        if (!isNaN(dt.getTime())) {
          biddingTime = dt.toLocaleTimeString('en-US', {
            hour: 'numeric', minute: '2-digit', hour12: true,
            timeZone: 'America/New_York'
          }) + ' ET';
        }
      } catch (e) {}
    }

    // --- Auction URL ---
    const auctionUrl = auctionId ? `https://www.bid4assets.com/auction/${auctionId}` : '';

    results.push({
      json: {
        property_address: address,
        county: county,
        state: state,
        source: 'Bid4Assets',
        status: status,
        current_bid: bid,
        bidding_date: biddingDate,
        bidding_time: biddingTime,
        sale_date: saleDate,
        auction_url: auctionUrl,
        time_remaining: timeRemaining,
        unique_id: ''
      }
    });
  }
}

console.log(`✅ ${results.length} active auctions passed, ${skipped} withdrawn/sold/closed skipped`);

if (results.length === 0) {
  return [{ json: {
    property_address: 'No active auctions found', county: 'N/A', state: '',
    source: 'Bid4Assets', status: 'Active', current_bid: 0,
    bidding_date: 'N/A', bidding_time: 'N/A', sale_date: 'N/A',
    auction_url: '', time_remaining: '', unique_id: 'skip'
  }}];
}

return results;

// ============================================================
// EXTRACT StorefrontId + CollectionIds from Kendo config
// ============================================================

const items = $input.all();
const results = [];

for (const item of items) {
  const html = item.json.data || '';
  const county = item.json.county || 'Unknown';
  const state = item.json.state || '';
  const slug = item.json.slug || '';

  if (!html || html.length < 500) {
    console.log(`⚠️ ${county}, ${state}: No valid HTML returned`);
    continue;
  }

  // --- Extract StorefrontId ---
  let storefrontId = null;
  const sfMatch = html.match(/"StorefrontId"\s*:\s*(\d+)/i)
    || html.match(/getauctiondisplay\/(\d+)/i)
    || html.match(/downloadpropertylist\/(\d+)/i)
    || html.match(/storefrontId\s*:\s*(\d+)/i);
  if (sfMatch) storefrontId = sfMatch[1];

  if (!storefrontId) {
    console.log(`⚠️ ${county}, ${state}: Could not find StorefrontId`);
    continue;
  }

  // --- Extract CollectionIds from Kendo data ---
  const collections = [];
  const kendoDataMatch = html.match(/"Data"\s*:\s*\[([\s\S]*?)\]\s*,\s*"Total"/i);
  if (kendoDataMatch) {
    try {
      const dataStr = '[' + kendoDataMatch[1] + ']';
      const folders = JSON.parse(dataStr);
      for (const folder of folders) {
        if (folder.StorefrontCollectionId) {
          collections.push({
            id: folder.StorefrontCollectionId,
            name: folder.CollectionName || '',
          });
        }
      }
    } catch (e) {
      // Fallback regex
      const collRegex = /"StorefrontCollectionId"\s*:\s*(\d+)/gi;
      let collMatch;
      while ((collMatch = collRegex.exec(html)) !== null) {
        collections.push({ id: parseInt(collMatch[1]), name: '' });
      }
    }
  }

  // --- Extract dates from timeline ---
  let startDate = 'N/A';
  let endDate = 'N/A';

  const startsMatch = html.match(/Starts<\/span>\s*<span[^>]*>([^<]+)/i);
  if (startsMatch) {
    const d = startsMatch[1].trim().match(/(\w+\s+\d{1,2},?\s+\d{4})/);
    if (d) startDate = d[1];
  }
  const endsMatch = html.match(/Ends<\/span>\s*<span[^>]*>([^<]+)/i);
  if (endsMatch) {
    const d = endsMatch[1].trim().match(/(\w+\s+\d{1,2},?\s+\d{4})/);
    if (d) endDate = d[1];
  }

  console.log(`✅ ${county}, ${state}: StorefrontId=${storefrontId}, Collections=${collections.length}`);

  // Output one item per collection
  if (collections.length > 0) {
    for (const coll of collections) {
      // Extract closing time from collection name
      let closingTime = 'Check Listing';
      const ct = coll.name.match(/Closing\s+at\s+([^"]+)/i);
      if (ct) closingTime = ct[1].trim();

      results.push({
        json: {
          county, state, slug, storefrontId,
          collectionId: coll.id,
          collectionName: coll.name,
          startDate, endDate, closingTime,
        }
      });
    }
  } else {
    console.log(`⚠️ ${county}, ${state}: No collections found`);
  }
}

if (results.length === 0) {
  return [{ json: { error: 'No storefronts returned valid data' } }];
}

return results;
